def run(context):
    # Analyze quarterly results and rank companies
    results = []
    for record in context['scores.quarterly_results']:
        if record['revenue'] and record['pat']:
            growth_score = (record['revenue'] + record['pat']) / 2
            results.append((record['symbol'], growth_score))
    results.sort(key=lambda x: x[1], reverse=True)
    return [symbol for symbol, score in results[:5]]

